// Common fields added to all issues
const defaults = { citations: [], communityRecommendations: [], status: 'published' };

async function main() {
  const allIssues = [...fordIssues, ...vwIssues, ...volvoIssues];
  let created = 0, skipped = 0;

  for (const issue of allIssues) {
    const data = { ...defaults, ...issue };
    try {
      await prisma.knownIssue.create({ data });
      created++;
      console.log('Created: ' + data.id);
    } catch (e) {
      skipped++;
      console.log('SKIP (exists): ' + data.id);
    }
  }

  console.log('\n=== SUMMARY ===');
  console.log('Total attempted: ' + allIssues.length);
  console.log('Created: ' + created);
  console.log('Skipped (already exist): ' + skipped);

  // Verify counts
  const fordModels = ['Tempo','C-Max','Excursion','E-Series','Windstar','EcoSport','Fiesta','Contour','Aerostar','Freestar','Escort','Freestyle','Five Hundred','F-350','Thunderbird','Flex','Probe','Explorer Sport Trac','F-250'];
  const vwModels = ['GTI','Eurovan','CC','Touareg','Golf Alltrack','New Beetle','Corrado','Phaeton','Atlas Cross Sport','Rabbit','Fox','Taos','ID.4','ID. Buzz','Cabrio','Arteon','Golf R','Eos'];
  const volvoModels = ['V40','V90','C70','C40 Recharge','V90 Cross Country','740','EX30','S90','240','960','XC40','V60','XC70','S70','EX90','V60 Cross Country','V50','S40','940','S80'];

  console.log('\n=== FINAL COUNTS ===');
  for (const [makeName, models] of [['Ford', fordModels], ['Volkswagen', vwModels], ['Volvo', volvoModels]]) {
    for (const model of models) {
      const count = await prisma.knownIssue.count({ where: { make: makeName, model } });
      console.log(makeName + ' ' + model + ': ' + count);
    }
  }

  const grandTotal = await prisma.knownIssue.count();
  console.log('\nGRAND TOTAL: ' + grandTotal);

  await pool.end();
  process.exit(0);
}

main();
